insert into public.sources
  (id, name, publisher, url, description, category, access, cadence, licence, caveat)
values
  ('worldbank-wdi', 'World Development Indicators', 'World Bank', 'https://datatopics.worldbank.org/world-development-indicators/', 'The World Bank''s compilation of internationally comparable statistics, assembled from national statistical offices and UN agencies. Queried live from this site through the open v2 API, which is why most long-run series here update themselves.', 'Multilateral', 'api', 'Continuous; major refreshes in April, July, September and December', 'CC BY 4.0', 'Values are as reported by the national statistical office and are revised without notice. Comparability across countries is the priority, so figures can differ slightly from the Indian domestic release for the same indicator.'),
  ('worldbank-pip', 'Poverty and Inequality Platform', 'World Bank', 'https://pip.worldbank.org/', 'The World Bank''s poverty measurement platform, source of the international poverty lines. In June 2025 the lines were rebased to 2021 PPPs, moving extreme poverty from $2.15 to $3.00 a day — which changes every headline poverty number, including India''s.', 'Multilateral', 'api', 'Twice yearly', 'CC BY 4.0', 'India''s poverty estimates rest on consumption surveys with a long gap between 2011-12 and 2022-23, and a changed questionnaire design. Comparisons across that break are contested and should be read as indicative of direction, not precision.'),
  ('imf-weo', 'World Economic Outlook Database', 'International Monetary Fund', 'https://www.imf.org/en/Publications/WEO/weo-database', 'The IMF''s macroeconomic database and the standard reference for cross-country GDP comparisons and for the forward projections used in the ranking charts here.', 'Multilateral', 'api', 'April and October, with January and July updates', 'IMF terms of use — free for non-commercial reuse with attribution', 'Anything beyond the current year is a projection, not an observation. Nominal-GDP league tables also move with the exchange rate, so a ranking can change without any change in output.'),
  ('un-wpp', 'World Population Prospects', 'United Nations, Department of Economic and Social Affairs', 'https://population.un.org/wpp/', 'The UN''s population estimates and projections, and the basis for the finding that India became the world''s most populous country during 2023.', 'Multilateral', 'bulk', 'Revised every two years', 'CC BY 3.0 IGO', 'India has not held a census since 2011, so recent Indian population figures are modelled estimates carried forward, not counts.'),
  ('undp-hdr', 'Human Development Report', 'United Nations Development Programme', 'https://hdr.undp.org/data-center', 'The Human Development Index and its components — life expectancy, schooling, and gross national income per head — used here as the counterweight to the aggregate-GDP story.', 'Multilateral', 'bulk', 'Annual', 'CC BY 3.0 IGO', 'Each report describes a reference year roughly two years earlier, and the index is periodically re-based, so rank changes between reports are not always real movement.'),
  ('wipo-gii', 'Global Innovation Index', 'World Intellectual Property Organization', 'https://www.wipo.int/global_innovation_index/en/', 'A composite ranking of national innovation capacity across around 80 indicators, used here to track India''s movement rather than its absolute score.', 'Multilateral', 'publication', 'Annual', 'CC BY 4.0 (report); indicator data under contributor terms', 'A composite index: the methodology and the sample of economies change between editions, so a rank series is only loosely comparable over time.'),
  ('knomad', 'Migration and Development Brief (remittances)', 'World Bank / KNOMAD', 'https://www.knomad.org/data/remittances', 'Global remittance estimates by receiving country — the series behind India being the world''s largest recipient of remittances.', 'Multilateral', 'bulk', 'Twice yearly', 'CC BY 4.0', 'Estimates combine balance-of-payments reporting with modelling, and informal channels are captured unevenly.'),
  ('unodc', 'Global Study on Homicide / UNODC data portal', 'United Nations Office on Drugs and Crime', 'https://dataunodc.un.org/', 'Internationally comparable intentional-homicide rates, used here to place India''s murder rate against the world average.', 'Multilateral', 'bulk', 'Annual', 'CC BY 3.0 IGO', 'Cross-country crime comparison is reliable only for homicide. Recorded rates for every other offence are dominated by differences in reporting and legal definition.'),
  ('sipri-milex', 'Military Expenditure Database', 'Stockholm International Peace Research Institute', 'https://www.sipri.org/databases/milex', 'Consistent estimates of military spending back to 1949, on a common definition that lets India be compared with other spenders.', 'Research institute', 'bulk', 'Annual, each April', 'Free for non-commercial use with attribution', 'SIPRI''s definition is broader than India''s defence budget line: it includes pensions and paramilitary forces, so SIPRI''s total is higher than the Ministry of Defence allocation for the same year.'),
  ('sipri-at', 'Arms Transfers Database', 'Stockholm International Peace Research Institute', 'https://www.sipri.org/databases/armstransfers', 'Volumes of international transfers of major conventional weapons, the source for India''s import dependence and for the shift in supplier mix away from Russia.', 'Research institute', 'bulk', 'Annual, each March', 'Free for non-commercial use with attribution', 'Measured in trend-indicator values (TIV), a volume measure of military capability — not money paid. TIV totals must never be read as dollars.'),
  ('owid', 'Our World in Data', 'Global Change Data Lab, University of Oxford', 'https://ourworldindata.org/', 'Curated and harmonised long-run series drawn from primary statistical agencies, used here where a clean comparable time series matters more than the latest observation.', 'Research institute', 'api', 'Continuous', 'CC BY 4.0', 'A re-publisher, not an originator — the underlying source is always cited alongside.'),
  ('iea', 'India energy statistics', 'International Energy Agency', 'https://www.iea.org/countries/india', 'Energy balances, electricity generation and emissions for India, used for the energy-transition figures.', 'Multilateral', 'publication', 'Annual, with periodic outlooks', 'IEA terms of use', null),
  ('mospi-nas', 'National Accounts Statistics', 'Ministry of Statistics and Programme Implementation', 'https://mospi.gov.in/national-accounts-statistics', 'India''s official GDP estimates — the primary release from which the World Bank and IMF India figures are ultimately derived.', 'Government of India', 'publication', 'Quarterly estimates; annual revisions in January and February', 'Government Open Data Licence — India', 'The 2011-12 base-year series is not directly comparable with the earlier 2004-05 series. A new base year revision is under way.'),
  ('mospi-plfs', 'Periodic Labour Force Survey', 'Ministry of Statistics and Programme Implementation', 'https://mospi.gov.in/web/mospi/download-tables-data/-/reports/view/templateFour/', 'The official household survey of employment, unemployment and labour-force participation, replacing the old quinquennial rounds with an annual (and now monthly) cadence.', 'Government of India', 'publication', 'Annual reports; quarterly urban bulletins; monthly from 2025', 'Government Open Data Licence — India', 'Headline unemployment uses "usual status", which counts anyone working 30 days or more in the year as employed, and counts unpaid family work as employment. Both choices lower the measured rate relative to intuitive definitions.'),
  ('mospi-cpi', 'Consumer Price Index', 'Ministry of Statistics and Programme Implementation', 'https://mospi.gov.in/cpi', 'The monthly inflation series the Reserve Bank targets.', 'Government of India', 'publication', 'Monthly', 'Government Open Data Licence — India', null),
  ('indiabudget', 'Union Budget documents', 'Ministry of Finance', 'https://www.indiabudget.gov.in/', 'Budget at a Glance, Expenditure Profile and Demands for Grants — the authoritative record for every allocation figure quoted here, including defence and capital expenditure.', 'Government of India', 'publication', 'Annual, each 1 February', 'Government Open Data Licence — India', 'A budget has three vintages: Budget Estimate, Revised Estimate and Actual. They differ, sometimes by a lot. Every budget figure here states which vintage it is.'),
  ('economic-survey', 'Economic Survey of India', 'Ministry of Finance, Department of Economic Affairs', 'https://www.indiabudget.gov.in/economicsurvey/', 'The government''s annual review of the economy, tabled the day before the Budget, and a consolidated source for reform-era statistics.', 'Government of India', 'publication', 'Annual', 'Government Open Data Licence — India', 'Authored by the government; the framing is official, though the underlying data are the standard official series.'),
  ('data-gov-in', 'Open Government Data Platform India', 'National Informatics Centre', 'https://data.gov.in/', 'India''s central open-data catalogue, exposing thousands of departmental datasets through a keyed REST API. Used here for departmental series that have no dedicated API of their own.', 'Government of India', 'api', 'Varies by dataset', 'Government Open Data Licence — India', 'Coverage is uneven and many resources stop being updated without being marked stale. Each dataset used here is checked for its own last-updated date.'),
  ('pib', 'Press Information Bureau releases', 'Government of India', 'https://www.pib.gov.in/', 'The official channel for ministry announcements and for parliamentary answers. Used where a number exists only in a ministry statement — chiefly defence production and scheme progress.', 'Government of India', 'publication', 'Daily', 'Government Open Data Licence — India', 'A press release is a primary source for what a ministry has stated, not an independently audited statistic. Figures sourced only to PIB are marked as such.'),
  ('mod-ddp', 'Department of Defence Production', 'Ministry of Defence', 'https://ddpmod.gov.in/', 'Defence production value, defence exports, indigenisation lists and the iDEX innovation programme — the primary record for the self-reliance figures.', 'Government of India', 'publication', 'Annual, with quarterly statements', 'Government Open Data Licence — India', 'Production value counts output of defence public-sector undertakings and private firms at sale value; it is not a measure of indigenous content, which is lower.'),
  ('mod-annual', 'Ministry of Defence Annual Report', 'Ministry of Defence', 'https://www.mod.gov.in/documents/annual-report', 'The consolidated annual account of the armed forces, acquisitions, R&D and the defence-industrial base.', 'Government of India', 'publication', 'Annual', 'Government Open Data Licence — India', null),
  ('drdo', 'Defence Research and Development Organisation', 'Ministry of Defence', 'https://www.drdo.gov.in/', 'Programme records for indigenous defence systems and test milestones.', 'Government of India', 'publication', 'Continuous', 'Government Open Data Licence — India', null),
  ('isro', 'Indian Space Research Organisation', 'Department of Space', 'https://www.isro.gov.in/', 'Launch records and mission outcomes, used for the space-programme figures.', 'Government of India', 'publication', 'Per mission', 'Government Open Data Licence — India', null),
  ('ncrb-cii', 'Crime in India', 'National Crime Records Bureau, Ministry of Home Affairs', 'https://www.ncrb.gov.in/crime-in-india.html', 'India''s annual crime statistics volume, compiled from state police returns — the only national crime series, and the basis for every crime figure here.', 'Government of India', 'publication', 'Annual, published with a lag of one to two years', 'Government Open Data Licence — India', 'These are recorded crimes, not crimes committed. NCRB counts under the "principal offence rule" — only the most serious charge in an incident is counted — so totals understate. Rising numbers can mean rising reporting, better registration, or rising crime, and the series cannot separate them.'),
  ('ncrb-psi', 'Prison Statistics India', 'National Crime Records Bureau, Ministry of Home Affairs', 'https://www.ncrb.gov.in/prison-statistics-india.html', 'Annual statistics on prison population, capacity, occupancy and the share of inmates awaiting trial.', 'Government of India', 'publication', 'Annual', 'Government Open Data Licence — India', null),
  ('njdg', 'National Judicial Data Grid', 'eCommittee, Supreme Court of India', 'https://njdg.ecourts.gov.in/', 'A live count of pending and disposed cases across district and high courts — one of the few genuinely real-time official datasets in Indian governance.', 'Government of India', 'api', 'Continuously updated', 'Government Open Data Licence — India', 'Pendency counts depend on court-level data entry and on how a "case" is defined; the total moves with digitisation as much as with disposal.'),
  ('bprd', 'Data on Police Organisations', 'Bureau of Police Research and Development', 'https://bprd.nic.in/publication-list?page_id=17', 'Sanctioned and actual police strength, expenditure and infrastructure by state — the capacity side of the law-and-order picture.', 'Government of India', 'publication', 'Annual, as on 1 January', 'Government Open Data Licence — India', null),
  ('mha-i4c', 'Indian Cyber Crime Coordination Centre', 'Ministry of Home Affairs', 'https://i4c.mha.gov.in/', 'The national cybercrime reporting portal and its statistics on financial-fraud complaints and amounts.', 'Government of India', 'publication', 'Continuous; periodic parliamentary statements', 'Government Open Data Licence — India', 'Portal complaints are reports, not verified losses, and the sharp rise partly reflects the portal itself becoming the standard reporting route.'),
  ('trai', 'Telecom subscription and performance indicator reports', 'Telecom Regulatory Authority of India', 'https://www.trai.gov.in/release-publication/reports', 'Monthly subscriber counts and quarterly indicators covering broadband, data consumption and tariffs.', 'Government of India', 'publication', 'Monthly and quarterly', 'Government Open Data Licence — India', 'Counts SIMs and connections, not people. One person with two active SIMs appears twice, so subscriber totals overstate the number of users.'),
  ('jal-jeevan', 'Jal Jeevan Mission dashboard', 'Department of Drinking Water and Sanitation', 'https://ejalshakti.gov.in/jjmreport/JJMIndia.aspx', 'Live reporting of rural household tap-water connections, by state and district.', 'Government of India', 'bulk', 'Continuously updated', 'Government Open Data Licence — India', 'Reports connections provided, which is not the same as water delivered reliably or of tested quality. Functionality assessments run separately and report lower numbers.'),
  ('swachh-bharat', 'Swachh Bharat Mission (Grameen) dashboard', 'Department of Drinking Water and Sanitation', 'https://sbm.gov.in/', 'Household toilet coverage and ODF status by village, block and district.', 'Government of India', 'bulk', 'Continuously updated', 'Government Open Data Licence — India', 'Self-declared administrative status. Independent surveys — including the National Family Health Survey — record usage below declared coverage.'),
  ('pmay', 'Pradhan Mantri Awas Yojana dashboards', 'Ministry of Rural Development / Ministry of Housing and Urban Affairs', 'https://pmayg.nic.in/netiayHome/home.aspx', 'Houses sanctioned, completed and handed over under the rural and urban housing missions.', 'Government of India', 'bulk', 'Continuously updated', 'Government Open Data Licence — India', null),
  ('pmjdy', 'Pradhan Mantri Jan Dhan Yojana progress', 'Department of Financial Services', 'https://pmjdy.gov.in/statewise-statistics', 'Weekly account, deposit and card statistics for the financial-inclusion programme.', 'Government of India', 'bulk', 'Weekly', 'Government Open Data Licence — India', 'Accounts opened is a stock measure that includes dormant accounts; deposits per account is the better indicator of use.'),
  ('niti-mpi', 'National Multidimensional Poverty Index', 'NITI Aayog', 'https://www.niti.gov.in/national-multidimensional-poverty-index', 'A twelve-indicator deprivation index built on National Family Health Survey data, covering health, education and standard of living.', 'Government of India', 'publication', 'Per NFHS round', 'Government Open Data Licence — India', 'Measures deprivation in basic amenities, not income. Because several indicators track scheme delivery directly, the index moves quickly when schemes scale — which is a real improvement in living conditions but not the same as a rise in earnings.'),
  ('nfhs', 'National Family Health Survey', 'International Institute for Population Sciences / Ministry of Health and Family Welfare', 'http://rchiips.org/nfhs/', 'India''s large-sample household health and demographic survey, and the independent check on scheme dashboards.', 'Government of India', 'publication', 'Roughly every five years', 'Free for research use', null),
  ('srs', 'Sample Registration System', 'Office of the Registrar General of India', 'https://censusindia.gov.in/census.website/data/SRSSTAT', 'The official vital-statistics system: birth and death rates, infant mortality, maternal mortality and life expectancy.', 'Government of India', 'publication', 'Annual bulletins; maternal mortality on a three-year moving average', 'Government Open Data Licence — India', 'Maternal mortality is published as a three-year average, so the latest available figure always lags by several years.'),
  ('cea', 'Central Electricity Authority', 'Ministry of Power', 'https://cea.nic.in/dashboard/', 'Installed generation capacity, generation and supply position, updated monthly.', 'Government of India', 'bulk', 'Monthly', 'Government Open Data Licence — India', null),
  ('morth', 'Ministry of Road Transport and Highways', 'Government of India', 'https://morth.nic.in/road-transport-year-books', 'National highway length, construction pace and road accident statistics.', 'Government of India', 'publication', 'Annual', 'Government Open Data Licence — India', null),
  ('dpiit-fdi', 'FDI Statistics', 'Department for Promotion of Industry and Internal Trade', 'https://dpiit.gov.in/publications/fdi-statistics', 'Quarterly foreign direct investment inflows by sector and source country.', 'Government of India', 'publication', 'Quarterly', 'Government Open Data Licence — India', 'Headline "FDI inflow" includes reinvested earnings and other capital; equity inflow is the narrower and more informative number.'),
  ('commerce-tradestat', 'Foreign trade statistics', 'Ministry of Commerce and Industry', 'https://tradestat.commerce.gov.in/', 'Merchandise and services export and import data by commodity and partner, the source for the export-composition figures.', 'Government of India', 'bulk', 'Monthly', 'Government Open Data Licence — India', 'Recent months are provisional and are routinely revised, services trade especially.'),
  ('gst-council', 'GST collections and council decisions', 'GST Council / Ministry of Finance', 'https://gstcouncil.gov.in/', 'Monthly gross GST collections and the record of rate decisions, including the 2025 rate rationalisation.', 'Government of India', 'publication', 'Monthly', 'Government Open Data Licence — India', 'Gross collections are not comparable with pre-2017 indirect tax receipts, and rise with both compliance and inflation as well as with real activity.'),
  ('ibbi', 'Insolvency and Bankruptcy Board of India quarterly newsletter', 'IBBI', 'https://ibbi.gov.in/en/publication', 'Case-level statistics on corporate insolvency resolution: admissions, resolutions, liquidations, realisation and time taken.', 'Government of India', 'publication', 'Quarterly', 'Government Open Data Licence — India', 'Recovery rates are computed against admitted claims, which typically far exceed the liquidation value of the firm. A low recovery rate often reflects how distressed a company was when it was admitted, not the process itself.'),
  ('ppac', 'Petroleum Planning and Analysis Cell', 'Ministry of Petroleum and Natural Gas', 'https://ppac.gov.in/', 'Consumption, import dependence and LPG coverage statistics for petroleum products.', 'Government of India', 'bulk', 'Monthly', 'Government Open Data Licence — India', null),
  ('rbi-dbie', 'Database on the Indian Economy', 'Reserve Bank of India', 'https://data.rbi.org.in/', 'The RBI''s statistical warehouse: money and banking, external sector, financial markets and government finances.', 'Reserve Bank of India', 'bulk', 'Weekly to annual, by series', 'Free to use with attribution', null),
  ('rbi-fsr', 'Financial Stability Report', 'Reserve Bank of India', 'https://www.rbi.org.in/Scripts/PublicationsView.aspx?id=0', 'Half-yearly assessment of banking-system health, and the source for the gross non-performing-asset series.', 'Reserve Bank of India', 'publication', 'Twice yearly', 'Free to use with attribution', 'The fall in reported bad loans reflects genuine recovery, but also write-offs, which remove loans from the ratio without recovering the money.'),
  ('rbi-handbook', 'Handbook of Statistics on the Indian Economy', 'Reserve Bank of India', 'https://www.rbi.org.in/Scripts/AnnualPublications.aspx?head=Handbook+of+Statistics+on+Indian+Economy', 'Long-run annual series on the Indian economy — the standard reference for anything needing a consistent multi-decade view.', 'Reserve Bank of India', 'bulk', 'Annual', 'Free to use with attribution', null),
  ('npci', 'UPI product statistics', 'National Payments Corporation of India', 'https://www.npci.org.in/what-we-do/upi/product-statistics', 'Monthly transaction volumes and values for the Unified Payments Interface and the other retail payment rails NPCI operates.', 'Industry body', 'bulk', 'Monthly', 'Free to use with attribution', 'Counts transactions, including very small and person-to-person transfers, so volume growth outpaces the growth in value and in economic activity.'),
  ('uidai', 'Aadhaar saturation and authentication statistics', 'Unique Identification Authority of India', 'https://uidai.gov.in/aadhaar_dashboard/', 'Enrolment, saturation and monthly authentication and e-KYC volumes.', 'Government of India', 'bulk', 'Continuously updated', 'Government Open Data Licence — India', null),
  ('dbt-bharat', 'Direct Benefit Transfer dashboard', 'DBT Mission, Cabinet Secretariat', 'https://dbtbharat.gov.in/', 'Scheme-wise transfers made directly to beneficiary accounts, and the government''s estimate of resulting savings.', 'Government of India', 'bulk', 'Continuously updated', 'Government Open Data Licence — India', 'The published "savings" figure is a government estimate combining removed duplicates with avoided leakage, and independent estimates of the same quantity differ substantially.')
